diff --git a/tests/fefo.test.js b/tests/fefo.test.js
new file mode 100644
index 0000000..b91fe93
--- /dev/null
+++ b/tests/fefo.test.js
@@ -0,0 +1,41 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { consume } from "../src/domain/batches.js";
+import { cook } from "../src/domain/recipes.js";
+import { fresh } from "./helpers.js";
+
+const at = "2026-10-28T10:00:00Z";
+const lotOf = (store, batchId) => store.data.batches.find((b) => b.id === batchId).lot;
+
+test("cooking bechamel takes the milk lot that expires first", () => {
+  const store = fresh();
+  const bechamel = store.data.recipes.find((r) => r.name === "bechamel");
+  const used = cook(store, bechamel.id, 10, { at });
+  const milk = used.find((u) => u.itemId === 2).batches;
+  assert.deepEqual(milk.map((u) => [lotOf(store, u.batchId), u.qty]), [["HD-1022", 2]]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+});
+
+test("consume spills over to the next batch to expire", () => {
+  const store = fresh();
+  const used = consume(store, 2, 3, { at });
+  assert.deepEqual(used.map((u) => [lotOf(store, u.batchId), u.qty]), [["HD-1022", 2], ["HD-1026", 1]]);
+});
+
+test("batches without expiry go last; ties go to first received, then lower id", () => {
+  const store = fresh();
+  const base = { itemId: 2, qty: 1, location: "fridge" };
+  store.data.batches = store.data.batches.filter((b) => b.itemId !== 2);
+  store.data.batches.push(
+    { ...base, id: 901, lot: "NONE", receivedOn: "2026-10-01", expires: null },
+    { ...base, id: 902, lot: "LATE", receivedOn: "2026-10-01", expires: "2026-11-05" },
+    { ...base, id: 904, lot: "TIE-HIGH-ID", receivedOn: "2026-10-20", expires: "2026-11-01" },
+    { ...base, id: 903, lot: "TIE-LOW-ID", receivedOn: "2026-10-20", expires: "2026-11-01" },
+    { ...base, id: 905, lot: "TIE-OLDER", receivedOn: "2026-10-19", expires: "2026-11-01" },
+  );
+  const used = consume(store, 2, 5, { at });
+  assert.deepEqual(
+    used.map((u) => lotOf(store, u.batchId)),
+    ["TIE-OLDER", "TIE-LOW-ID", "TIE-HIGH-ID", "LATE", "NONE"],
+  );
+});
